fixtures.scripts/dev-server.mjs:
// Loopback-only development server for the desktop client.
import http from "node:http";
const port = Number(process.env.PORT ?? 3000);
const server = http.createServer((req, res) => {
  if (req.url === "/health") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ ok: true }));
    return;
  }
  res.writeHead(404).end();
});
server.listen(port, "127.0.0.1", () => console.log("listening on http://127.0.0.1:" + port));

fixtures.scripts/check-api.mjs:
// Offline compatibility harness: synthetic inputs, a loopback recorder and no remote calls.
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const only = process.argv.find((a) => a.startsWith("--only="))?.slice("--only=".length) ?? "all";
if (process.argv.includes("--list")) {
  console.log("placement-text\nautomatic-overflow\nautomatic-threshold\nresume\nreact-fixture\nfixtures\nsafe-tools\nreasoning-xhigh\nfailing");
  process.exit(0);
}
const names = only === "all" ? ["placement-text", "automatic-overflow", "automatic-threshold", "resume"] : [only];
const seen = [];
const server = http.createServer((req, res) => {
  seen.push({ url: req.url, method: req.method });
  res.writeHead(200, { "content-type": "application/json" });
  res.end(JSON.stringify({ ok: true }));
});
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const base = "http://127.0.0.1:" + server.address().port;
let failed = 0;
for (const name of names) {
  const response = await fetch(base + "/" + name, { method: "POST", body: JSON.stringify({ case: name, synthetic: true }) });
  const body = await response.json();
  const ok = body.ok === true;
  console.log((ok ? "PASS " : "FAIL ") + name + " (synthetic loopback)");
  if (!ok) failed++;
}
fs.mkdirSync(".scratch", { recursive: true });
fs.writeFileSync(path.join(".scratch", "compat-results.json"), JSON.stringify({ only, seen, failed }, null, 2));
server.close();
if (only === "failing") process.exitCode = 1;

